"""Centralised configuration loaded from environment variables.

Values are read lazily on first access so that tests can monkeypatch env
vars before the module is imported.
"""

from __future__ import annotations

import os

# ── Defaults (used when the env var is unset) ───────────────────────

_DEFAULTS: dict[str, str | None] = {
    # Slack — required (no default)
    "SLACK_BOT_TOKEN": None,
    "SLACK_SIGNING_SECRET": None,
    "SLACK_APP_TOKEN": None,
    # User token (xoxp-) generated by a Workspace Admin/Owner, used solely to
    # write a member's GitHub username into their Slack profile after an org
    # invite. Optional: when unset, the write-back silently no-ops.
    "SLACK_ADMIN_USER_TOKEN": None,
    # GitHub
    "GITHUB_TOKEN": None,
    "GITHUB_ORG": "nf-core",
    # Seqera Platform workspace sync (all optional; disabled without credentials/IDs).
    "SEQERA_TOKEN": None,
    "SEQERA_ORG_ID": None,
    "SEQERA_WORKSPACE_ID": None,
    "SEQERA_WORKSPACE_ROLE": "nf-core-read-only",
    # Weekly removal job only logs who it would remove until set to "false".
    "SEQERA_REMOVAL_DRY_RUN": "true",
    # DynamoDB
    "DYNAMODB_TABLE": "nf-core-bot",
    "DYNAMODB_ENDPOINT": None,  # None → real AWS
    "AWS_REGION": "eu-west-1",
    # Permissions
    "CORE_TEAM_USERGROUP_HANDLE": "core-team",
    "MAINTAINERS_USERGROUP_HANDLE": "maintainers-team",
    # Channels
    "ONCALL_CHANNEL": "core",
    "SECURITY_CHANNEL": "security",
    # Calendar (S3 + CloudFront)
    "CALENDAR_S3_BUCKET": None,
    "CALENDAR_CLOUDFRONT_DOMAIN": None,
    # Pipeline-proposal reviews
    "PROPOSALS_CHANNEL": "new-pipelines",
    "PROPOSALS_REVIEW_ENABLED": "true",
    # Bedrock model ID — an inference-profile ID in eu-west-1 (note the "eu." prefix).
    "BEDROCK_MODEL_ID": "eu.anthropic.claude-sonnet-4-6",
    # Region for the Bedrock client; falls back to AWS_REGION when unset.
    "BEDROCK_REGION": None,
    "BEDROCK_MAX_TOKENS": "12000",
    # Thinking mode passed to the model: "adaptive" (default) or "off".
    "BEDROCK_THINKING": "adaptive",
    # Read-only GitHub token for the proposal-review CLI tool; falls back to
    # GITHUB_TOKEN when unset (the tool allowlist is read-only regardless).
    "PROPOSALS_GITHUB_TOKEN": None,
}

_REQUIRED: frozenset[str] = frozenset(["SLACK_BOT_TOKEN", "SLACK_SIGNING_SECRET", "SLACK_APP_TOKEN", "GITHUB_TOKEN"])


def _get(name: str) -> str | None:
    """Resolve a config value from the environment, falling back to defaults."""
    value = os.environ.get(name)
    if value:
        return value
    default = _DEFAULTS.get(name)
    if default is not None:
        return default
    if name in _REQUIRED:
        raise RuntimeError(f"Missing required environment variable: {name}")
    return None


def __getattr__(name: str) -> str | None:
    """Module-level ``__getattr__`` — makes config values importable as attributes.

    Usage::

        from nf_core_bot.config import SLACK_BOT_TOKEN
    """
    if name in _DEFAULTS:
        return _get(name)
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")
